const vec2  F_AK       = vec2(.05, .0);
const float F_LAIGHTER = 24.;
#define NICER_BLUR     3. 

#define MIRROR_TEXTURE 
#define LABEL_IMPLEMENTATIONS

// rest of the macros are just for laziness

#define USE_LAIGHTER_GRAY_ // 'bout the same...

#define V(o)       (value_at(st,o))
#define V3(a,b,c)  (vec3(V(a), V(b), V(c)))
#define NV3(a,b,c) normalize(V3(a,b,c))

#define TX   iChannel0
#define TXR  iChannelResolution[0].xy
#define KB   iChannel1
#define FONT iChannel2

vec4 raw_at(vec2 st, vec2 offset) {
    return texture(TX, (st + offset) / TXR);
}

vec4 rgba_at(vec2 st, vec2 offset) {
    if (keyToggle(13, KB)) {
        #ifdef NICER_BLUR
            float sum = .0;
            vec4 accumulator = vec4(sum);
            for (float x = 1. ; x <= NICER_BLUR ; x++) {
                for (float y = 1. ; y <= NICER_BLUR ; y++) {
                    vec2 blur_offset = vec2(x,y) * offset;
                    float d = distance(blur_offset, offset);
                    float weight = pow(1.33, d);
                    sum += weight;
                    vec4 color = raw_at(st, blur_offset);
                    accumulator += weight * color;
                }
            }
            return accumulator / sum;
        #else
            return (
                + 1.5 * raw_at(st, offset)
                + .75 * raw_at(st, offset.yx)
                + .75 * raw_at(st, offset.xy*2.)
            )/3.;
        #endif
    }

    return raw_at(st, offset);
}

float value_at(vec2 st, vec2 offset) {
    vec4 v = rgba_at(st, offset);
    //return v.g; // works fine usually

#ifdef USE_LAIGHTER_GRAY
    return 0.2126 * v.r + 0.7152 * v.g + 0.0722 * v.b;
#else
    return (v.x + v.y + v.z) / 3.;
#endif
}

// from Alexander Konstantinov
// https://stackoverflow.com/questions/5281261/generating-a-normal-map-from-a-height-map
vec3 bumpAK(in vec2 st, in vec2 size, in vec3 o) {
    float x0 = value_at(st, o.xy);
    float x1 = value_at(st, o.zy);
    float y0 = value_at(st, o.yx);
    float y1 = value_at(st, o.yz);
    float dx = x0 - x1;
    float dy = y0 - y1;
    vec3 va = normalize(vec3(F_AK.xy, -dx));
    vec3 vb = normalize(vec3(F_AK.yx, -dy));
    return cross(va,vb);
}

// Azagaya's Laighter is the gold standard 
// this is hugely simplified but my favorite of the 4
// https://github.com/azagaya/godot_normalMap_generator
vec3 bumpLaighter(in vec2 st, in vec2 size, in vec3 o) {   
	float x0 = value_at(st, o.xy);
	float x1 = value_at(st, o.zy);
	float y0 = value_at(st, o.yx);
	float y1 = value_at(st, o.yz);
    float dx = x0 - x1;
    float dy = y0 - y1;
    return normalize(vec3(dx * F_LAIGHTER, dy * F_LAIGHTER, 1.));
}

// this was sort of how I remembered it... 
// but the high frency is a sort of nuts
vec3 bumpMeine(in vec2 st, in vec2 size, in vec3 o) {
    vec3 b0 = V3(o.xy, o.yx, o.xx);
    vec3 b1 = V3(o.zy, o.yz, o.zz);
    return normalize(b0 - b1);
}

// messin' about as usual :-P
vec3 bumpMe(in vec2 st, in vec2 size, in vec3 o) {   
	float x0 = value_at(st, o.xy);
	float x1 = value_at(st, o.zy);
	float y0 = value_at(st, o.yx);
	float y1 = value_at(st, o.yz);
    float dx = x0 - x1;
    float dy = y0 - y1;

    //float f = 16.; dx *= f; dy*=f;
    //return normalize(vec3(dx, dy, 1.-(abs(dx)+abs(dy))));

    //vec3 q = vec3(-.1, 2., 1.);
    //return normalize(q.zxy * dx + q.xzy * dy);

    float quantization = 16.;
    dx = floor(dx * quantization) / quantization;
    dy = floor(dy * quantization) / quantization;

    return normalize(o.zyz * dx + o.yzz * dy + o.yyz * .0001);
}

void mainImage(out vec4 result, in vec2 tx) {
    vec2 rz = iResolution.xy;
    vec2 size = TXR;

    vec2 og = tx;
    float which = step(rz.x *.5, og.x) + step(og.y, rz.y *.5) * 2.; 

    tx = mod(tx * 2., rz);
#ifdef MIRROR_TEXTURE
    // mirror texture to ease comparison
    switch(int(which)) {
        case 1: tx.x = rz.x - tx.x; 
        case 0: tx.y = rz.y - tx.y; break;
        case 3: tx.x = rz.x - tx.x; break;
    }
#endif   
    vec2 st = mod(tx, size);    
    const vec3 o = vec3(-1., .0, 1.);

    vec3 bump = o.yyz;
    switch(int(which + (keyToggle(8,KB)?3.e3:.0))) {
        case 0: bump = bumpAK(st, size, o); break;
        case 1: bump = bumpLaighter(st, size, o); break;
        case 2: bump = bumpMeine(st, size, o); break;
        case 3: bump = bumpMe(st, size, o); break;
    }

    vec2 uv = pixelToUv(og, rz);
    if (keyToggle(32,iChannel1)) {
        result.rgb = bump;
    } else {
        vec3 color = raw_at(st, o.yy).xyz;

        vec3 uv3 = vec3(uv, .0);
        vec3 light = vec3(pixelToUv(iMouse.xy, iResolution.xy), 1.);

        float strength = .5;
        float lume = (1.-strength) + strength * dot(uv3+bump, light-uv3);

        result.rgb = color * lume;
    } 

#ifdef LABEL_IMPLEMENTATIONS
    float d = 3e3, x = 1.6, y = .88, q = x * .7, f = .16;
    d = min(d, STRING((uv - vec2(-x, +y))/f, str_ak,       FONT));
    d = min(d, STRING((uv - vec2(+q, +y))/f, str_laighter, FONT));
    d = min(d, STRING((uv - vec2(+x, -y))/f, str_mine,     FONT));
    d = min(d, STRING((uv - vec2(-x, -y))/f, str_me,       FONT));
    if (keyToggle(13, KB)) {
        d = min(d, .88*STRING((uv - vec2(.0, y))/f*2., str_blur,     FONT));
    }

    float c = distanceToShape( d, .01 );
    result.rbg = mix(
        result.rbg,
        mix(vec3(.0), vec3(1.), c),
        step(d,.6)

    );
#endif
}

vec2 pixelToUv( vec2 st, vec2 resolution ) {
    return ( st * 2. - resolution.xy ) / min( resolution.x, resolution.y );
}

bool keyToggle( int key, sampler2D keyboardChannel ) {
    return .0 < texelFetch( keyboardChannel, ivec2(key,2), 0 ).x;
}

// from my font stuff over in /tlccWN
#define STRING    stringDistance
#define CHAR      characterDistance
#define STRIDE(n) ((n)*vec2( .5, .0 ))
#define C(n)      ((string >> (n*8)) & 0xFF)
#define STYPE     ivec2
// https://luckybit4755.github.io/shady-lady/html/text-to-ivec4.html
const int blank = 538976288;

const int str_ak         = 538987329;
const STYPE str_laighter = STYPE(1734959436, 1919251560);
const int str_mine       = 538993997;
const int str_me         = 1701734733;
const STYPE str_blur     = STYPE(1381321794, 541345106);

float characterDistance(vec2 point, int character, sampler2D font) {
    vec2 charAt = vec2( character % 16, 15 - character / 16 ) / 16. + 1./32.;    
    float w = textureLod( font, charAt + point / 16., .0 ).w;
    vec2 box = abs( point / .8 );
    return max( w, max( box.x, box.y ) );
}

float stringDistance(vec2 point, int string, sampler2D font) {
    return 
        min(CHAR(point,              C(0), font ),
        min(CHAR(point - STRIDE(1.), C(1), font ),
        min(CHAR(point - STRIDE(2.), C(2), font ),
            CHAR(point - STRIDE(3.), C(3), font ))));
}

float stringDistance(vec2 point, STYPE string, sampler2D font) {
    return
        min(stringDistance(point - STRIDE(0. * 4.), string[0], font),
        stringDistance(point - STRIDE(1. * 4.), string[1], font)
        );/*,
        min(stringDistance(point - STRIDE(2. * 4.), string[2], font),
            stringDistance(point - STRIDE(3. * 4.), string[3], font))));
            */
}

float distanceToShape(float d, float t) {
    return smoothstep(.5 - t, .5 + t, 1.-d);
}
